以下是一个简单的量化策略演示（Python伪代码）：

```python
# 函数：计算简单移动平均
def sma(data, window):
    return data.rolling(window).mean()

# 类：双均线策略
class DualMAStrategy:
    def __init__(self, short_window=5, long_window=20):
        self.short_window = short_window
        self.long_window = long_window
        self.position = 0  # 0空仓，1持仓
        self.signals = []

    def generate_signals(self, price_series):
        short_ma = sma(price_series, self.short_window)
        long_ma = sma(price_series, self.long_window)
        # 当短期均线上穿长期均线时买入
        for i in range(len(price_series)):
            if i > self.long_window:
                if short_ma[i] > long_ma[i] and short_ma[i-1] <= long_ma[i-1]:
                    self.signals.append(1)
                    self.position = 1
                elif short_ma[i] < long_ma[i] and short_ma[i-1] >= long_ma[i-1]:
                    self.signals.append(-1)
                    self.position = 0
                else:
                    self.signals.append(0)
            else:
                self.signals.append(0)
        return self.signals

# 使用
data = [10,11,12,13,14,15,14,13]  # 简化股价
strategy = DualMAStrategy(short_window=2, long_window=3)
signals = strategy.generate_signals(data)
print(signals)  # 输出买卖信号
```

实际量化中，你会用`pandas`处理真实数据，并将策略类与回测引擎、数据源等组合。通过函数和面向对象，你可以快速测试不同参数，而无需重写底层逻辑。
